import "@tanstack/react-start/server-only"

import { redirect } from "@tanstack/react-router"
import { getRequest, setResponseHeader } from "@tanstack/react-start/server"
import { betterAuth } from "better-auth"
import { drizzleAdapter } from "better-auth/adapters/drizzle"
import { tanstackStartCookies } from "better-auth/tanstack-start"

import { getServerEnv } from "@/env"
import type { ServerEnv } from "@/env"
import { resolveAllowedHosts } from "@/lib/auth/origins"
import { getDb } from "@/lib/db"
import * as schema from "@/lib/db/schema/auth"

export type SessionUser = {
  id: string
  name: string
  email: string
  image?: string | null
}

/**
 * Local dev works without flipping .env: plain Vite (loopback Host) and Portless (`*.localhost`,
 * public URL in PORTLESS_URL). Production stays pinned to BETTER_AUTH_URL plus the optional
 * BETTER_AUTH_TRUSTED_ORIGINS. Do not hard-code a hostname or port; see `origins.ts`.
 */
function resolveBaseURL(env: ServerEnv) {
  const extra = env.BETTER_AUTH_TRUSTED_ORIGINS
  return {
    allowedHosts: resolveAllowedHosts({
      nodeEnv: env.NODE_ENV,
      betterAuthUrl: env.BETTER_AUTH_URL,
      portlessUrl: env.PORTLESS_URL,
      extraTrustedOrigins: extra
        ? extra
            .split(",")
            .map((s) => s.trim())
            .filter(Boolean)
        : undefined,
    }),
    fallback: env.BETTER_AUTH_URL,
    protocol: "auto" as const,
  }
}

function createAuth() {
  const env = getServerEnv()
  return betterAuth({
    secret: env.BETTER_AUTH_SECRET.reveal(),
    baseURL: resolveBaseURL(env),
    // Portless (and real reverse proxies) set x-forwarded-*; honor them so
    // protocol=auto and cookie Secure match the browser origin.
    advanced: {
      trustedProxyHeaders: true,
    },
    database: drizzleAdapter(getDb(), {
      provider: "pg",
      schema: {
        user: schema.user,
        session: schema.session,
        account: schema.account,
        verification: schema.verification,
      },
    }),
    session: {
      // Signed cookie avoids a DB read per request; revocation lags by up to maxAge.
      cookieCache: { enabled: true, maxAge: 300 },
    },
    emailAndPassword: {
      enabled: true,
      // Above the 8-char default. Turn on `requireEmailVerification` once an email
      // transport exists - enabling it before that locks every new signup out.
      minPasswordLength: 12,
    },
    // tanstackStartCookies() MUST stay the LAST plugin: any plugin after it loses its Set-Cookie
    // headers without an error (TanStack/router#8911). Add new plugins above it.
    plugins: [tanstackStartCookies()],
  })
}

// oxlint-disable-next-line anti-slop/no-return-type-utility -- Better Auth's generic return type has no writable name; the plugin list shapes it.
export type Auth = ReturnType<typeof createAuth>

let authInstance: Auth | undefined

export function getAuth() {
  authInstance ??= createAuth()
  return authInstance
}

export async function getSessionUser(headers: Headers): Promise<SessionUser | null> {
  try {
    const session = await getAuth().api.getSession({ headers })
    const user = session?.user
    if (!user) return null
    return { id: user.id, name: user.name, email: user.email, image: user.image }
  } catch (error) {
    console.error("getSessionUser failed", error)
    return null
  }
}

/**
 * The auth gate for every server fn: call it first. A thrown `redirect()` is the only error Start
 * turns into navigation; a custom Error becomes an opaque 500. It also marks the response
 * `no-store`, so no proxy or browser cache keeps a per-user answer.
 */
export async function requireUser(): Promise<SessionUser> {
  setResponseHeader("Cache-Control", "no-store")
  const user = await getSessionUser(getRequest().headers)
  if (!user) throw redirect({ to: "/login" })
  return user
}

import { createServerFn } from "@tanstack/react-start"
import { getRequest } from "@tanstack/react-start/server"

import { getSessionUser } from "@/lib/auth/server"
import type { SessionUser } from "@/lib/auth/server"

export type { SessionUser }

/** Session for routes and components. Returns null when signed out - it never redirects. */
export const $getSessionUser = createServerFn({ method: "GET" }).handler(async () =>
  getSessionUser(getRequest().headers),
)

import { matchesHostPattern } from "better-auth"

export type ResolveAllowedHostsInput = {
  /** `development` | `test` | `production` - loopback patterns only when not production. */
  nodeEnv: string | undefined
  /** Canonical fallback origin (e.g. `BETTER_AUTH_URL`). */
  betterAuthUrl: string
  /** Public URL injected by Portless (`PORTLESS_URL`), if present. */
  portlessUrl?: string | undefined
  /**
   * Extra full origins or host patterns (e.g. from `BETTER_AUTH_TRUSTED_ORIGINS`).
   * Hosts are extracted so dynamic `baseURL` can resolve them; Better Auth also
   * appends the raw env CSV to trustedOrigins natively.
   */
  extraTrustedOrigins?: string[] | undefined
}

/** Extract `host[:port]` from a URL or return a host/pattern as-is. */
export function hostFromUrlOrPattern(value: string): string {
  const trimmed = value.trim()
  if (!trimmed) return ""
  try {
    if (trimmed.includes("://")) return new URL(trimmed).host
  } catch {
    // fall through - treat as host or wildcard pattern
  }
  return trimmed.replace(/^https?:\/\//, "").split("/")[0] ?? ""
}

/**
 * Better Auth `baseURL.allowedHosts` from env signals, with no hard-coded hostname or port.
 * Development and test add `.localhost` and loopback on any port. Production allows only
 * `betterAuthUrl` and the optional extras.
 */
export function resolveAllowedHosts(input: ResolveAllowedHostsInput): string[] {
  const hosts = new Set<string>()

  const fallbackHost = hostFromUrlOrPattern(input.betterAuthUrl)
  if (fallbackHost) hosts.add(fallbackHost)

  if (input.portlessUrl) {
    const portlessHost = hostFromUrlOrPattern(input.portlessUrl)
    if (portlessHost) hosts.add(portlessHost)
  }

  for (const extra of input.extraTrustedOrigins ?? []) {
    const host = hostFromUrlOrPattern(extra)
    if (host) hosts.add(host)
  }

  if (input.nodeEnv !== "production") {
    // Plain Vite / loopback - Host may be bare or include any port.
    hosts.add("localhost")
    hosts.add("localhost:*")
    hosts.add("127.0.0.1")
    hosts.add("127.0.0.1:*")
    // Portless (and any named local HTTPS): app name and nested worktrees.
    // Better Auth wildcards match multi-label names (`feature.app.localhost`).
    hosts.add("*.localhost")
    hosts.add("*.localhost:*")
  }

  return [...hosts]
}

/** True when `host` matches any allowed host pattern (Better Auth rules). */
export function isHostAllowed(host: string, allowedHosts: readonly string[]): boolean {
  return allowedHosts.some((pattern) => matchesHostPattern(host, pattern))
}

/// <reference types="bun" />
import { describe, expect, test } from "bun:test"

import { hostFromUrlOrPattern, isHostAllowed, resolveAllowedHosts } from "@/lib/auth/origins"

const prodUrl = "https://app.example.com"
const localFallback = "https://myapp.localhost"

describe("hostFromUrlOrPattern", () => {
  test("extracts host from absolute URLs", () => {
    expect(hostFromUrlOrPattern("https://myapp.localhost")).toBe("myapp.localhost")
    expect(hostFromUrlOrPattern("http://localhost:4308")).toBe("localhost:4308")
  })

  test("keeps bare host and wildcard patterns", () => {
    expect(hostFromUrlOrPattern("*.localhost")).toBe("*.localhost")
    expect(hostFromUrlOrPattern("  app.example.com  ")).toBe("app.example.com")
  })
})

describe("resolveAllowedHosts (development)", () => {
  test("allows any loopback port via class patterns, not a fixed port list", () => {
    const hosts = resolveAllowedHosts({
      nodeEnv: "development",
      // Fallback host may include a port; wildcards still cover other ports.
      betterAuthUrl: "http://localhost:3000",
    })

    expect(isHostAllowed("localhost:4308", hosts)).toBe(true)
    expect(isHostAllowed("localhost:5173", hosts)).toBe(true)
    expect(isHostAllowed("127.0.0.1:9999", hosts)).toBe(true)
    expect(isHostAllowed("localhost", hosts)).toBe(true)
    // Dual-mode mechanism is class wildcards - not app-name or fixed-port entries.
    expect(hosts).toContain("localhost:*")
    expect(hosts).toContain("*.localhost")
    expect(hosts.some((h) => h === "localhost:4308")).toBe(false)
    expect(hosts.some((h) => h.includes("myapp"))).toBe(false)
  })

  test("allows Portless-style .localhost and nested worktree hosts without naming the app", () => {
    const hosts = resolveAllowedHosts({
      nodeEnv: "development",
      betterAuthUrl: localFallback,
    })

    expect(isHostAllowed("myapp.localhost", hosts)).toBe(true)
    expect(isHostAllowed("feature.myapp.localhost", hosts)).toBe(true)
    expect(isHostAllowed("other-app.localhost", hosts)).toBe(true)
  })

  test("includes PORTLESS_URL host when present", () => {
    const hosts = resolveAllowedHosts({
      nodeEnv: "development",
      betterAuthUrl: localFallback,
      portlessUrl: "https://myapp.localhost",
    })

    expect(hosts).toContain("myapp.localhost")
    expect(isHostAllowed("myapp.localhost", hosts)).toBe(true)
  })

  test("merges explicit extra trusted origins as hosts", () => {
    const hosts = resolveAllowedHosts({
      nodeEnv: "development",
      betterAuthUrl: localFallback,
      extraTrustedOrigins: ["https://preview.example.com", "staging.example.com"],
    })

    expect(isHostAllowed("preview.example.com", hosts)).toBe(true)
    expect(isHostAllowed("staging.example.com", hosts)).toBe(true)
  })
})

describe("resolveAllowedHosts (production)", () => {
  test("only allows BETTER_AUTH_URL host and optional extras", () => {
    const hosts = resolveAllowedHosts({
      nodeEnv: "production",
      betterAuthUrl: prodUrl,
    })

    expect(hosts).toEqual(["app.example.com"])
    expect(isHostAllowed("app.example.com", hosts)).toBe(true)
    expect(isHostAllowed("evil.com", hosts)).toBe(false)
    expect(isHostAllowed("localhost:4308", hosts)).toBe(false)
    expect(isHostAllowed("myapp.localhost", hosts)).toBe(false)
    expect(isHostAllowed("feature.myapp.localhost", hosts)).toBe(false)
  })

  test("PORTLESS_URL alone does not open production to loopback wildcards", () => {
    const hosts = resolveAllowedHosts({
      nodeEnv: "production",
      betterAuthUrl: prodUrl,
      portlessUrl: "https://myapp.localhost",
    })

    expect(hosts).toContain("app.example.com")
    expect(hosts).toContain("myapp.localhost")
    expect(hosts).not.toContain("localhost:*")
    expect(hosts).not.toContain("*.localhost")
    expect(isHostAllowed("evil.com", hosts)).toBe(false)
    expect(isHostAllowed("other-app.localhost", hosts)).toBe(false)
  })

  test("optional extras expand production allowlist only for listed hosts", () => {
    const hosts = resolveAllowedHosts({
      nodeEnv: "production",
      betterAuthUrl: prodUrl,
      extraTrustedOrigins: ["https://cdn.example.com"],
    })

    expect(isHostAllowed("cdn.example.com", hosts)).toBe(true)
    expect(isHostAllowed("evil.com", hosts)).toBe(false)
  })
})

import { createFileRoute } from "@tanstack/react-router"

/** Better Auth owns every /api/auth/* route. Imported lazily so the client bundle never pulls it. */
export const Route = createFileRoute("/api/auth/$")({
  server: {
    handlers: {
      GET: async ({ request }) => {
        const { getAuth } = await import("@/lib/auth/server")
        return getAuth().handler(request)
      },
      POST: async ({ request }) => {
        const { getAuth } = await import("@/lib/auth/server")
        return getAuth().handler(request)
      },
    },
  },
})

import { Link, Outlet, createFileRoute, redirect, useRouter } from "@tanstack/react-router"

import { Button } from "@/components/ui/button"
import { signOut } from "@/lib/auth/client"
import { $getSessionUser } from "@/lib/auth/session"

/**
 * Everything under src/routes/_authed/ requires a session. The gate runs in `beforeLoad`, so a
 * signed-out visitor never renders the page - and server fns gate again via `requireUser()`.
 */
export const Route = createFileRoute("/_authed")({
  beforeLoad: async () => {
    const user = await $getSessionUser()
    if (!user) throw redirect({ to: "/login" })
    return { user }
  },
  // The page HTML names the signed-in user: no shared or browser cache may keep it.
  headers: () => ({ "Cache-Control": "no-store" }),
  component: AuthedLayout,
})

function AuthedLayout() {
  const { user } = Route.useRouteContext()
  const router = useRouter()

  async function handleSignOut() {
    await signOut()
    await router.invalidate()
    await router.navigate({ to: "/login" })
  }

  return (
    <div className="mx-auto flex min-h-svh max-w-2xl flex-col gap-6 px-6 py-10">
      <header className="flex items-center justify-between gap-4 border-b border-border pb-4">
        <Link to="/" className="text-sm font-medium">
          Home
        </Link>
        <div className="flex items-center gap-3">
          <span className="text-sm text-muted-foreground">{user.email}</span>
          <Button variant="outline" size="sm" onClick={() => void handleSignOut()}>
            Sign out
          </Button>
        </div>
      </header>
      <Outlet />
    </div>
  )
}

import { createFileRoute, redirect } from "@tanstack/react-router"

import { LoginPage } from "@/features/auth/login-page"
import { $getSessionUser } from "@/lib/auth/session"

export const Route = createFileRoute("/login")({
